<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { listAppCanteens, listAppStalls } from '../../api/app'
import type { Canteen, Stall } from '../../api/types'
import { ElMessage } from 'element-plus'
const router = useRouter(); const canteens = ref<Canteen[]>([]); const stallsByCanteen = ref<Record<number, Stall[]>>({}); const loading = ref(true)
const stallCount = computed(() => Object.values(stallsByCanteen.value).reduce((n, list) => n + list.length, 0))
onMounted(async () => { try { canteens.value = await listAppCanteens(); await Promise.all(canteens.value.map(async (c) => { stallsByCanteen.value[c.id] = await listAppStalls(c.id) })) } catch (e) { ElMessage.error((e as Error).message) } finally { loading.value = false } })
</script>
<template><div class="mobile-page home-page"><section class="service-banner"><div class="banner-top"><span>今日校园餐饮</span><span class="service-open">供餐中</span></div><h1>预约取餐</h1><p>先选食堂和档口，再按自己的时间取餐。</p><div class="banner-meta"><div><b>{{ canteens.length }}</b><span>个食堂</span></div><div><b>{{ stallCount }}</b><span>个档口</span></div><div><b>6位</b><span>取餐码</span></div></div></section><section class="date-strip"><div class="today"><span>今日供餐</span><b>{{ new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'}) }}</b></div><div class="date-note"><span>午餐高峰</span><b>11:00 - 13:00</b></div></section><div v-loading="loading" class="canteen-list"><div class="section-title"><div><h2>选择食堂</h2><p>按食堂查看开放档口</p></div><span>共 {{ canteens.length }} 个</span></div><section v-for="canteen in canteens" :key="canteen.id" class="canteen-block"><div class="canteen-head"><div><h3>{{ canteen.name }}</h3><p>{{ canteen.address }}</p></div><span class="open-time">{{ canteen.openTime }}-{{ canteen.closeTime }}</span></div><div class="stall-list"><button v-for="stall in stallsByCanteen[canteen.id]" :key="stall.id" class="stall-row" @click="router.push(`/student/menu/${stall.id}`)"><div class="stall-index">{{ String(stall.id).padStart(2, '0') }}</div><div class="stall-main"><strong>{{ stall.name }}</strong><span>{{ stall.location }} · {{ stall.description }}</span></div><span class="enter-text">进入</span><span class="chevron">›</span></button></div></section><div v-if="!loading && !canteens.length" class="empty">暂未查询到开放食堂</div></div></div></template>
